#!/usr/bin/env node
/**
 * EV Charging Demand & Grid Load Analytics
 * Read-Only MongoDB Telemetry Verification Script
 *
 * Verifies connectivity to MongoDB and inspects the `grid_telemetry` collection
 * to ensure telemetry records generated by the simulator are persisted.
 */

import fs from "node:fs";
import path from "node:path";
import { MongoClient } from "mongodb";

// 1. Auto-load .env.local if present
const envLocalPath = path.resolve(process.cwd(), ".env.local");
if (fs.existsSync(envLocalPath)) {
  try {
    const lines = fs.readFileSync(envLocalPath, "utf-8").split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eqIdx = trimmed.indexOf("=");
      if (eqIdx > 0) {
        const key = trimmed.slice(0, eqIdx).trim();
        const val = trimmed.slice(eqIdx + 1).trim().replace(/^['"]|['"]$/g, "");
        if (process.env[key] === undefined) {
          process.env[key] = val;
        }
      }
    }
  } catch (err) {
    console.warn(`[warning] Could not read .env.local: ${err.message}`);
  }
}

const MONGODB_URI = process.env.MONGODB_URI || "mongodb://127.0.0.1:27017";
const MONGODB_DB_NAME = process.env.MONGODB_DB_NAME || "ev_charging_analytics";
const COLLECTION_NAME = "grid_telemetry";

console.log("================================================================");
console.log("   EV CHARGING ANALYTICS — MONGODB TELEMETRY VERIFIER");
console.log("================================================================\n");

// Mask password in URI for safe console logging if present
const maskedUri = MONGODB_URI.replace(
  /\/\/(.*?):(.*?)@/,
  "//$1:******@"
);

console.log(`[config] Target URI:       ${maskedUri}`);
console.log(`[config] Target Database:  ${MONGODB_DB_NAME}`);
console.log(`[config] Target Collection: ${COLLECTION_NAME}\n`);

let client;

async function checkTelemetry() {
  try {
    console.log("[status] Connecting to MongoDB...");
    client = new MongoClient(MONGODB_URI, {
      serverSelectionTimeoutMS: 4000,
      connectTimeoutMS: 4000,
    });

    await client.connect();

    // Verify connectivity with a ping
    const adminDb = client.db("admin");
    await adminDb.command({ ping: 1 });
    console.log("[status] Connection successful (MongoDB is reachable)\n");

    const db = client.db(MONGODB_DB_NAME);
    const collection = db.collection(COLLECTION_NAME);

    // Get total document count (read-only)
    const count = await collection.countDocuments();
    console.log(`[telemetry] Total records in '${COLLECTION_NAME}': ${count}`);

    if (count === 0) {
      console.log("\n[notice] The collection is currently empty.");
      console.log("         To generate telemetry records, run:");
      console.log("           npm run simulator:once");
      console.log("         or start the live background simulator:");
      console.log("           npm run simulator:start\n");
      return;
    }

    // Fetch latest 5 documents sorted by recorded_at descending
    const latestDocs = await collection
      .find({})
      .sort({ recorded_at: -1 })
      .limit(5)
      .toArray();

    console.log(`\n--- Latest ${latestDocs.length} Telemetry Records (Sorted by recorded_at DESC) ---\n`);

    latestDocs.forEach((doc, idx) => {
      const recDate = doc.recorded_at instanceof Date
        ? doc.recorded_at.toISOString()
        : String(doc.recorded_at);

      const stationId = doc.station_id ?? "N/A";
      const stationName = doc.metadata?.station_name ?? `Station #${stationId}`;
      const voltage = doc.voltage_v != null ? `${Number(doc.voltage_v).toFixed(1)} V` : "N/A";
      const current = doc.current_a != null ? `${Number(doc.current_a).toFixed(1)} A` : "N/A";
      const power = doc.power_kw != null ? `${Number(doc.power_kw).toFixed(2)} kW` : "N/A";
      const frequency = doc.frequency_hz != null ? `${Number(doc.frequency_hz).toFixed(2)} Hz` : "N/A";
      const gridLoad = doc.grid_load_kw != null ? `${Number(doc.grid_load_kw).toFixed(2)} kW` : "N/A";
      const capacity = doc.metadata?.capacity_kw != null ? `${doc.metadata.capacity_kw} kW` : "N/A";
      const scenario = doc.metadata?.scenario ?? "normal";
      const overloaded = doc.metadata?.is_overloaded ? "YES (OVERLOADED)" : "NO";

      console.log(`Record #${idx + 1}: [ID: ${doc._id}]`);
      console.log(`  Station:    ${stationName} (ID: ${stationId})`);
      console.log(`  RecordedAt: ${recDate}`);
      console.log(`  EV Power:   ${power} / Capacity: ${capacity}`);
      console.log(`  Grid Load:  ${gridLoad}`);
      console.log(`  Bus Voltage: ${voltage} | Current: ${current} | Frequency: ${frequency}`);
      console.log(`  Scenario:   ${scenario} | Overloaded: ${overloaded}`);
      console.log(`  Source:     ${doc.source ?? "simulated"}`);
      console.log("  --------------------------------------------------------------");
    });

    console.log("\n[summary] MongoDB telemetry verification completed successfully.");

  } catch (err) {
    console.error("\n[error] Telemetry verification failed!");
    if (err.name === "MongoServerSelectionError" || err.message?.includes("ECONNREFUSED")) {
      console.error(`        Could not connect to MongoDB at '${maskedUri}'.`);
      console.error("        Please ensure your MongoDB service or container is running.");
    } else {
      console.error(`        Details: ${err.message}`);
    }
    process.exitCode = 1;
  } finally {
    if (client) {
      await client.close();
      console.log("[status] MongoDB client connection closed.\n");
    }
  }
}

checkTelemetry();
